llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C35"],
      "claim": "Labetalol, a high-extraction drug with extensive first-pass metabolism, has an oral bioavailability of only 18% in humans, providing affirmative threshold-relevant evidence that a similarly high-extraction lipophilic drug can fall below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Rosuvastatin, the closest statin analogue, has an estimated absolute oral bioavailability of about 20%, which is at the threshold and therefore the strongest evidence for the high side, but it is borderline and does not establish that the query exceeds 20%.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C23"],
      "claim": "Propranolol, despite high transferability, shows a mean systemic availability of 38% in normal subjects, supporting the high side; however, its bioavailability is dose-dependent and can be as low as 16%, so it does not override the low-F pattern of high-extraction drugs.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is atorvastatin, a lipophilic statin with an anilide and dihydroxy-heptanoic acid side chain. The closest statin analogue rosuvastatin has F≈20%, at the threshold, but the query's greater lipophilicity and CYP3A4-mediated first-pass metabolism align better with high-extraction drugs such as labetalol (F≈18%) and the low end of propranolol (F≈16%), supporting F<20%.",
  "evidence_gaps": [
    "No direct atorvastatin bioavailability record is present in the evidence set.",
    "The closest statin analogue rosuvastatin has F≈20%, which is borderline for the threshold.",
    "Query-specific CYP3A4 metabolism and transporter-mediated clearance data are not directly evidenced."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

